/* audio/graph.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function rememberAudioDom() {
    return { parent: P.audio.parentNode, next: P.audio.nextSibling };
  }

  // APlayer and jPlayer create their own <audio> with document.createElement.
  // Handing them the shared element keeps one source of truth for playback;
  // the element is moved back into the player bar once the library is built.
  function withSharedAudioElement(factory) {
    const original = document.createElement;
    document.createElement = function (tagName, options) {
      if (String(tagName).toLowerCase() === "audio") return P.audio;
      return original.call(document, tagName, options);
    };
    try { return factory(); } finally { document.createElement = original; }
  }

  function restoreAudioDom(position) {
    if (!position?.parent) return;
    if (P.audio.parentNode === position.parent && P.audio.nextSibling === position.next) return;
    if (position.next && position.next.parentNode === position.parent) {
      position.parent.insertBefore(P.audio, position.next);
    } else {
      position.parent.appendChild(P.audio);
    }
  }

  // One AudioContext is shared by Peaks and Waviz. Browsers allow only one
  // MediaElementSource per element per context, so cache the node too.
  function sharedAudioContext() {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    if (!P.audioContext) {
      P.audioContext = new AudioContextClass();
      const createSource = P.audioContext.createMediaElementSource.bind(P.audioContext);
      P.audioContext.createMediaElementSource = (element) => {
        if (element === P.audio && P.mediaSourceNode) return P.mediaSourceNode;
        const node = createSource(element);
        if (element === P.audio) P.mediaSourceNode = node;
        return node;
      };
    }
    if (P.audioContext.state === "suspended") P.audioContext.resume().catch(() => {});
    return P.audioContext;
  }

  // Route the shared <audio> through a GainNode so fades are sample-accurate
  // (no zipper noise from stepping audio.volume). User volume stays on
  // audio.volume; this gain is only for transition envelopes.
  function ensureMainGain() {
    const context = P.sharedAudioContext();
    if (!context) return null;
    if (P.mainGainNode) return { context, gain: P.mainGainNode };
    if (!P.mediaSourceNode) {
      try {
        // Use the patched createMediaElementSource which caches the node.
        P.mediaSourceNode = context.createMediaElementSource(P.audio);
      } catch {
        return null;
      }
    }
    if (!P.mediaSourceNode) return null;
    try {
      P.ensureLimiter();
      P.mainGainNode = context.createGain();
      P.mainGainNode.gain.value = 1;
      P.mediaSourceNode.connect(P.mainGainNode);
      P.connectMainOutput();
    } catch {
      P.mainGainNode = null;
      return null;
    }
    return { context, gain: P.mainGainNode };
  }

  function destroyHowl() {
    if (!P.howl) return;
    const sound = P.howl._sounds && P.howl._sounds[0];
    if (sound && sound._node === P.audio) {
      P.audio.removeEventListener("error", sound._errorFn);
      P.audio.removeEventListener((window.Howler && window.Howler._canPlayEvent) || "canplaythrough", sound._loadFn);
      P.audio.removeEventListener("ended", sound._endFn);
    }
    const list = window.Howler && window.Howler._howls;
    const index = list ? list.indexOf(P.howl) : -1;
    if (index >= 0) list.splice(index, 1);
    P.howl = null;
  }

  function destroyWaviz() {
    if (P.wavizPlayHandler) { P.audio.removeEventListener("play", P.wavizPlayHandler); P.wavizPlayHandler = null; }
    if (P.wavizPauseHandler) { P.audio.removeEventListener("pause", P.wavizPauseHandler); P.wavizPauseHandler = null; }
    if (P.waviz) {
      try { P.waviz.stop(); } catch {}
      // Do not call waviz.cleanup(): it would close the shared AudioContext.
      P.waviz = null;
    }
    P.wavizCanvas?.remove();
    P.wavizCanvas = null;
  }

  // Some engines keep native listeners on the shared <audio> even after a
  // switch. Pause them while their engine is still current so they cannot
  // fight the next engine for control of the same element.
  function pauseExternalEngines() {
    if (P.state.engine === "amplitude" && window.Amplitude) {
      try { window.Amplitude.pause(); } catch {}
      // Detach Amplitude from the shared element; its next init creates a new
      // private Audio internally, so no stale callbacks remain on ours.
      try { window.Amplitude.getConfig().audio = new Audio(); } catch {}
    }
    if (P.state.engine === "aplayer" && P.aplayer) {
      try { P.aplayer.pause(); } catch {}
    }
    if (P.state.engine === "mediaelement" && P.mediaElementWrapper) {
      try { P.mediaElementWrapper.pause(); } catch {}
    }
    if (P.state.engine === "jplayer" && P.jplayerHost && window.jQuery) {
      try { window.jQuery(P.$("labJPlayerMedia")).jPlayer("pause"); } catch {}
    }
  }

  function destroyWaveforms() {
    P.pauseExternalEngines();
    P.waveform?.removeEventListener("dblclick", P.handleWaveDoubleClick);
    if (P.waveSurfer) {
      try { P.waveSurfer.destroy(); } catch {}
      P.waveSurfer = null;
    }
    if (P.peaks) {
      try { P.peaks.destroy(); } catch {}
      P.peaks = null;
    }
    P.destroyHowl();
    P.destroyWaviz();
    P.waveform?.replaceChildren();
    P.hideEngineUi();
  }
  Object.assign(P, { rememberAudioDom, withSharedAudioElement, restoreAudioDom, sharedAudioContext, ensureMainGain, destroyHowl, destroyWaviz, pauseExternalEngines, destroyWaveforms });
}
